import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { modalities, schedule, site } from "../data/ecvo-content.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const generatedNote = "<!-- This file is generated by scripts/generate-modality-pages.mjs. Edit data/ecvo-content.mjs instead. -->";

const escapeHtml = (value) => String(value)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

const jsonLd = (value) => JSON.stringify(value).replaceAll("<", "\\u003c");

const pageUrl = (slug) => `${site.url}/${slug}/`;
const whatsappUrl = (modality) => `https://wa.me/${site.whatsapp}?text=${encodeURIComponent(`Olá! Encontrei a ECVO pela página de ${modality.name} e gostaria de saber como participar do primeiro treino.`)}`;
const whatsappIcon = `<svg viewBox="0 0 32 32" width="26" height="26" aria-hidden="true"><path fill="currentColor" d="M16 3C9.4 3 4 8.4 4 15c0 2.1.5 4.1 1.6 5.9L4 29l8.3-1.5c1.7.9 3.6 1.4 5.7 1.4 6.6 0 12-5.4 12-12S22.6 3 16 3zm0 21.8c-1.8 0-3.5-.5-5-1.4l-.4-.2-4.9.9.9-4.8-.2-.4c-1-1.6-1.5-3.4-1.5-5.3 0-5.6 4.6-10.2 10.2-10.2S26.2 9.4 26.2 15 21.6 24.8 16 24.8zm5.6-7.6c-.3-.2-1.8-.9-2.1-1-.3-.1-.5-.2-.7.2-.2.3-.8 1-.9 1.2-.2.2-.3.2-.6.1-.3-.2-1.3-.5-2.5-1.5-.9-.8-1.5-1.8-1.7-2.1-.2-.3 0-.5.1-.6.1-.1.3-.3.4-.5.2-.2.2-.3.3-.5.1-.2 0-.4 0-.5-.1-.2-.7-1.6-.9-2.2-.2-.6-.5-.5-.7-.5h-.6c-.2 0-.5.1-.8.4-.3.3-1 1-1 2.5s1.1 2.9 1.2 3.1c.2.2 2.1 3.2 5.1 4.5.7.3 1.3.5 1.7.6.7.2 1.4.2 1.9.1.6-.1 1.8-.7 2-1.5.3-.7.3-1.4.2-1.5-.1-.1-.3-.2-.6-.4z" /></svg>`;

function analytics() {
  return `    <script async src="https://www.googletagmanager.com/gtag/js?id=G-381LW2ZL4V"></script>
    <script>
      window.dataLayer = window.dataLayer || [];
      function gtag() { dataLayer.push(arguments); }
      gtag("js", new Date());
      gtag("config", "G-381LW2ZL4V");
    </script>`;
}

function renderHeader(modality, whatsapp) {
  return `    <a class="skip-link" href="#conteudo">Pular para o conteúdo</a>
    <header class="site-header" aria-label="Topo">
      <a class="brand" href="/" aria-label="ECVO início">
        <img class="brand-logo" src="../assets/ecvo-simbolo-escuro.png" alt="" width="56" height="56" />
        <span class="brand-name"><strong>Escola de Combate</strong><span>Vinicius Oliveira</span></span>
      </a>
      <nav aria-label="Navegação principal">
        <a href="/modalidades/">Modalidades</a>
        <a href="#horarios">Horários</a>
        <a href="#localizacao">Como chegar</a>
        <a class="nav-app-link" href="${whatsapp}" data-track="whatsapp_click" data-cta-position="header">Quero ${escapeHtml(modality.name)}</a>
      </nav>
    </header>`;
}

function renderSchedule(modality) {
  const days = schedule.map(({ day, classes }) => ({
    day,
    classes: classes.filter(([, slugs]) => slugs.split(" ").includes(modality.slug)),
  })).filter(({ classes }) => classes.length);

  const hasPublishedSchedule = days.length > 0;

  return `      <section class="section modality-schedule" id="horarios" aria-labelledby="horarios-title">
        <div class="section-heading">
          <p class="eyebrow">Horários de ${escapeHtml(modality.name)}</p>
          <h2 id="horarios-title">${hasPublishedSchedule ? "Encontre seu espaço na semana." : "Horários ainda não disponíveis."}</h2>
${hasPublishedSchedule ? `          <p class="method-intro">Confira a grade atual da modalidade. Para confirmar disponibilidade, fale com a equipe.</p>` : ""}
        </div>
${hasPublishedSchedule ? `
        <div class="modality-schedule-grid">
${days.map(({ day, classes }) => `          <article class="modality-day">
            <h3>${day}</h3>
            <ul>
${classes.map(([time, , className]) => `              <li><time>${time}</time><span><strong>${className}</strong></span></li>`).join("\n")}
            </ul>
          </article>`).join("\n")}
        </div>
` : ""}
      </section>`;
}

function homeScheduleClass(slugs) {
  if (slugs.includes("muay-thai")) return "muaythai";
  if (slugs.includes("kickboxing")) return "kickboxing";
  if (slugs.includes("karate")) return "karate";
  if (slugs.includes("boxe")) return "boxe";
  if (slugs.includes("mma")) return "mma";
  return "nogi";
}

function renderHomeSchedule() {
  return `<div class="horarios-grid">
${schedule.map(({ day, classes }) => `          <article class="dia" data-reveal>
            <header class="dia-head"><h3>${day}</h3><span class="dia-count">${classes.length} aula${classes.length === 1 ? "" : "s"}</span></header>
            <ul class="dia-aulas">
${classes.map(([time, slugs, name]) => `              <li class="aula" data-mod="${homeScheduleClass(slugs)}"><span class="aula-hora">${time}</span><span class="aula-info"><span class="aula-nome">${name}</span></span></li>`).join("\n")}
            </ul>
          </article>`).join("\n")}
        </div>`;
}

function renderRelated(modality) {
  const bySlug = new Map(modalities.map((item) => [item.slug, item]));
  return `      <section class="section related-modalities" aria-labelledby="relacionadas-title">
        <div class="section-heading"><p class="eyebrow">Continue explorando</p><h2 id="relacionadas-title">Modalidades relacionadas.</h2></div>
        <div class="related-modalities-grid">
${modality.related.map((slug) => {
  const related = bySlug.get(slug);
  return `          <a href="/${related.slug}/"><span>Conheça também</span><strong>${escapeHtml(related.name)}</strong><small>${escapeHtml(related.hero)}</small></a>`;
}).join("\n")}
        </div>
      </section>`;
}

